const RE = /^:::(note|warning)\n([\s\S]*?)\n:::$/gm;

function admonitions(src) {
  return src.replace(RE, (_, kind, body) =>
    `<div class="admonition ${kind}">\n\n${body}\n\n</div>`);
}

module.exports = { admonitions };

