const fs = require('fs');
const path = require('path');

function tree(dir) {
  return fs.readdirSync(dir, { withFileTypes: true })
    .sort((a, b) => a.name.localeCompare(b.name, 'en', { numeric: true }))
    .map(e => e.isDirectory()
      ? { title: e.name.replace(/^\d+-/, ''), children: tree(path.join(dir, e.name)) }
      : { title: e.name.replace(/^\d+-|\.md$/g, ''), file: path.join(dir, e.name) });
}
module.exports = { tree };

