const { toUrl } = require('../links/normalize');

function sidebar(nodes, current) {
  const items = nodes.map(n => n.children
    ? `<li><span>${n.title}</span>${sidebar(n.children, current)}</li>`
    : `<li class="${n.file === current ? 'active' : ''}"><a href="/${toUrl(n.file)}">${n.title}</a></li>`);
  return `<ul>${items.join('')}</ul>`;
}
module.exports = { sidebar };

