const store = require('./store');
const { render } = require('../../markdown/render');

function cachedRender(key, source) {
  const hit = store.get(key);
  if (hit) return hit;
  const html = render(source);
  store.set(key, html);
  return html;
}
module.exports = { cachedRender };

