const crypto = require('crypto');
const memo = new Map();

function key(content) {
  return crypto.createHash('sha1').update(content).digest('hex');
}
function remember(content, parse) {
  const k = key(content);
  if (!memo.has(k)) memo.set(k, parse(content));
  return memo.get(k);
}
module.exports = { remember };

