const chokidar = require('chokidar');

function watchNative(dir, onChange) {
  return chokidar.watch(dir, { ignoreInitial: true, usePolling: false })
    .on('add', onChange)
    .on('change', onChange)
    .on('unlink', onChange);
}

module.exports = { watchNative };

