function debounce(fn, ms = 50) {
  const pending = new Set();
  let t;
  return file => {
    pending.add(file);
    clearTimeout(t);
    t = setTimeout(() => { fn([...pending]); pending.clear(); }, ms);
  };
}
module.exports = { debounce };

