const fs = require('fs');
const path = require('path');
const DIR = '.docforge/cache/pages';

function invalidate(changedFiles, keyOf) {
  for (const f of changedFiles) {
    const entry = path.join(DIR, keyOf(f) + '.html');
    if (fs.existsSync(entry)) fs.unlinkSync(entry);
  }
}
module.exports = { invalidate };

